public static int identifySpoiledBottle(int N) throws IOException {
    int friends = (int) Math.ceil(Math.log(N) / Math.log(2));
    int[] distribution = new int[friends];
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < friends; j++) {
            if ((i & (1 << j)) != 0) {
                distribution[j] = i + 1;
                System.out.println("Friend " + j + " gets bottle " + (i + 1));
            }
        }
    }

    BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
    String[] upsetFriends = reader.readLine().split(" ");

    int spoiledBottle = 0;
    for (String friend : upsetFriends) {
        int friendIndex = Integer.parseInt(friend);
        spoiledBottle |= (1 << friendIndex);
    }

    return spoiledBottle;
}

